export class PubSub {
  constructor() {
    this.topics = {};
  }

  subscribe(topic, listener) {
    if (!this.topics[topic]) {
      this.topics[topic] = [];
    }
    this.topics[topic].push(listener);
  }

  publish(topic, data) {
    if (!this.topics[topic]) return;
    this.topics[topic].forEach(listener => listener(data));
  }

  escalate(topic, priority = 0) {
    // Implement escalation logic based on priority
    console.log(`Escalating topic: ${topic} with priority: ${priority}`);
  }
}

